WITH valid AS (SELECT *, CAST(amount AS INT) AS amount_int, COALESCE(merchant, 'NONE') AS merchant_filled FROM transactions WHERE merchant IS NOT NULL AND amount >= 1500) SELECT id, account_id, txn_type, amount, txn_time, amount_int, merchant_filled, RANK() OVER (PARTITION BY account_id, txn_type ORDER BY amount DESC NULLS FIRST) AS amount_rank, DENSE_RANK() OVER (PARTITION BY merchant, txn_type ORDER BY amount_int) AS amount_int_dense_rank, LAG(amount, 1, 0) OVER (PARTITION BY account_id ORDER BY amount_int, id) AS prev_amount FROM valid;
